"""Parse SUMO emission-output electricity generated by MMPEVEM."""
from __future__ import annotations
import math
import xml.etree.ElementTree as ET

def mmpevem_emission_energy(path):
    gross_wh = 0.0
    regenerated_wh = 0.0
    samples = 0
    invalid = 0
    for _, elem in ET.iterparse(path, events=("end",)):
        if elem.tag != "vehicle":
            continue
        raw = elem.get("electricity")
        if raw is None:
            continue
        try:
            value = float(raw)
        except ValueError:
            invalid += 1
            elem.clear()
            continue
        if not math.isfinite(value):
            invalid += 1
        elif value >= 0:
            gross_wh += value
            samples += 1
        else:
            regenerated_wh += -value
            samples += 1
        elem.clear()
    if samples == 0:
        raise ValueError("No finite MMPEVEM electricity samples in emission output.")
    if invalid:
        raise ValueError(f"MMPEVEM emission output contains {invalid} invalid electricity samples.")
    return {
        "gross_energy_kWh": gross_wh / 1000.0,
        "regenerated_energy_kWh": regenerated_wh / 1000.0,
        "net_energy_kWh": (gross_wh - regenerated_wh) / 1000.0,
        "electricity_samples": samples,
    }
